<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Encryption/Decryption UI</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
  <style>
    body {
      background-color: #f4f4f9;
    }

    .container {
      border: 1px solid #ddd;
      padding: 30px;
      margin-top: 50px;
      border-radius: 10px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
      background-color: #fff;
      max-width: 600px;
    }

    .form-label {
      font-weight: bold;
    }

    .btn {
      width: 100%;
      padding: 10px;
      font-size: 16px;
    }

    .btn-primary {
      background-color: #007bff;
      border-color: #007bff;
    }

    .btn-secondary {
      background-color: #6c757d;
      border-color: #6c757d;
    }

    .label-section {
      border: 1px dashed #ccc;
      padding: 15px;
      background-color: #f9f9f9;
      text-align: center;
      border-radius: 5px;
      color: #555;
    }

    .row {
      margin-bottom: 15px;
    }
  </style>
</head>

<body>
  <div class="container">
    <div class="key-section mb-4">
      <label for="key" class="form-label">Key</label>
      <input type="text" id="key" class="form-control" placeholder="Enter key here">
    </div>

    <div class="row">
      <div class="col-md-6">
        <label for="plaintext" class="form-label">Plain Text to Encrypt</label>
        <input type="text" id="plaintext" class="form-control" placeholder="Enter plain text">
      </div>
      <div class="col-md-6">
        <label for="encryptedtext" class="form-label">Encrypted Text to Decrypt</label>
        <input type="text" id="encryptedtext" class="form-control" placeholder="Enter encrypted text">
      </div>
    </div>

    <div class="row">
      <div class="col-md-6">
        <button id="encrypt-btn" class="btn btn-primary">Encrypt</button>
      </div>
      <div class="col-md-6">
        <button id="decrypt-btn" class="btn btn-secondary">Decrypt</button>
      </div>
    </div>

    <div class="row mt-4">
      <div class="col-md-6">
        <div class="label-section">
          <span id="encrypted-label">Encrypted Value Will Appear Here</span>
        </div>
      </div>
      <div class="col-md-6">
        <div class="label-section">
          <span id="decrypted-label">Decrypted Value Will Appear Here</span>
        </div>
      </div>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
</body>

</html>
